def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    if not isinstance(value, datetime.time):
        raise TypeError("dehydrate_time expects a datetime.time instance, got %r" % type(value))
    if value.microsecond:
        # Include milliseconds (trim microseconds to milliseconds)
        return value.strftime("%H:%M:%S.%f")[:-3]
    return value.strftime("%H:%M:%S")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        raise ValueError("value cannot be None")
    try:
        lat = getattr(value, 'lat')
        lon = getattr(value, 'lon')
        time = getattr(value, 'time')
    except AttributeError as exc:
        raise TypeError("value must have 'lat', 'lon', and 'time' attributes") from exc

    # Convert time to ISO format string if it's a datetime-like object
    if hasattr(time, 'isoformat'):
        time_str = time.isoformat()
    else:
        time_str = str(time)

    return {'lat': lat, 'lon': lon, 'time': time_str}

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer explicit storage if available
        if hasattr(self, 'data') and isinstance(self.data, dict):
            return list(self.data.keys())
        if hasattr(self, 'record') and isinstance(self.record, dict):
            return list(self.record.keys())
        # Fallback to instance dictionary, excluding private attributes and callables
        return [k for k in self.__dict__
                if not k.startswith('_') and not callable(getattr(self, k))]
    except Exception as e:
        raise RuntimeError(f"Failed to retrieve keys: {e}") from e

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the mapping of handlers defined on the class.
    # It may be stored under a variety of names; the most common
    # is PROTOCOL_HANDLERS.  If it is missing, treat as empty.
    handlers = getattr(cls, "PROTOCOL_HANDLERS", {})
    # Normalise to a dictionary if a list of tuples is provided.
    if isinstance(handlers, list):
        handlers = dict(handlers)
    if not isinstance(handlers, dict):
        # If the attribute exists but is not a dict/list, we cannot
        # work with it; treat as empty to avoid breaking callers.
        handlers = {}

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )
        # Return a dict containing the handler if the version is supported.
        return (
            {protocol_version: handlers[protocol_version]}
            if protocol_version in handlers
            else {}
        )
    # No specific version requested; return all supported handlers.
    return dict(handlers)

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._index.index(key)
    except AttributeError:
        raise AttributeError("The object has no attribute '_index'")
    except ValueError:
        raise KeyError(key)

def values(self, *keys):
    """Return the values of the record, optionally filtering to include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to get items in insertion order
    try:
        items = list(self.items())
    except AttributeError:
        # Fallback: if the object has a _items attribute that is a list of dicts,
        # use the first dict to infer the order of keys.
        if hasattr(self, "_items") and isinstance(self._items, list) and self._items:
            try:
                items = list(self._items[0].items())
            except Exception:
                items = []
        else:
            items = []

    # If no keys are specified, return all values
    if not keys:
        return [value for _, value in items]

    result = []
    for k in keys:
        if isinstance(k, int):
            # Treat as index
            try:
                result.append(items[k][1])
            except IndexError:
                raise IndexError(f"Index {k} out of range for record with {len(items)} items")
        else:
            # Treat as key
            try:
                result.append(self[k])
            except KeyError:
                raise KeyError(f"Key {k!r} not found in record")
            except TypeError:
                # self may not support key lookup
                raise TypeError(f"Record does not support key lookup for {k!r}")
    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no keys provided, return all
    if not keys:
        return {name: self._data[i] for i, name in enumerate(self._keys)}
    result = {}
    for key in keys:
        if isinstance(key, int):
            idx = key
            if idx < 0 or idx >= len(self._data):
                raise IndexError(f"Index {idx} out of bounds")
            name = self._keys[idx]
            result[name] = self._data[idx]
        elif isinstance(key, str):
            if key in self._keys:
                idx = self._keys.index(key)
                result[key] = self._data[idx]
            else:
                result[key] = None
        else:
            raise TypeError("Keys must be int or str")
    return result

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate mode
        if mode is None:
            mode = "WRITE"
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be 'READ' or 'WRITE'")

        # Validate bookmarks
        if bookmarks is not None:
            if isinstance(bookmarks, (str, bytes)):
                raise ValueError("bookmarks must be an iterable of bookmark values")
            try:
                bookmarks = list(bookmarks)
            except Exception as exc:
                raise ValueError("bookmarks must be an iterable") from exc

        # Validate metadata
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError("metadata must be a dict")

        # Validate timeout
        if timeout is not None and not isinstance(timeout, (int, float)):
            raise ValueError("timeout must be a number")

        # Validate db
        if db is not None and not isinstance(db, str):
            raise ValueError("db must be a string")

        # Validate imp_user
        if imp_user is not None and not isinstance(imp_user, str):
            raise ValueError("imp_user must be a string")

        # Validate dehydration_hooks
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise ValueError("dehydration_hooks must be a dict")
            for typ, func in dehydration_hooks.items():
                if not isinstance(typ, type):
                    raise ValueError("dehydration_hooks keys must be types")
                if not callable(func):
                    raise ValueError("dehydration_hooks values must be callables")

        # Validate hydration_hooks
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise ValueError("hydration_hooks must be a dict")
            for typ, func in hydration_hooks.items():
                if not isinstance(typ, type):
                    raise ValueError("hydration_hooks keys must be types")
                if not callable(func):
                    raise ValueError("hydration_hooks values must be callables")

        # Prepare message id
        if not hasattr(self, "_next_message_id"):
            self._next_message_id = 0
        message_id = self._next_message_id
        self._next_message_id += 1

        # Build the BEGIN message
        message = {
            "id": message_id,
            "type": "BEGIN",
            "mode": mode
        }
        if bookmarks is not None:
            message["bookmarks"] = bookmarks
        if metadata is not None:
            message["metadata"] = metadata
        if timeout is not None:
            message["timeout"] = timeout
        if db is not None:
            message["db"] = db
        if imp_user is not None:
            message["imp_user"] = imp_user
        if dehydration_hooks is not None:
            message["dehydration_hooks"] = dehydration_hooks
        if hydration_hooks is not None:
            message["hydration_hooks"] = hydration_hooks

        # Append to the output queue
        if not hasattr(self, "_output_queue"):
            raise AttributeError("Output queue not initialized")
        self._output_queue.append(message)

        # Create and return a Response object
        try:
            response = Response(message_id, handlers)
        except NameError as exc:
            raise NameError("Response class is not defined") from exc
        return response

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        # Append the deprecation message to the function's docstring
        existing_doc = func.__doc__ or ""
        wrapper.__doc__ = existing_doc + ("\n\n" if existing_doc else "") + message
        return wrapper
    return decorator

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    def decorator(func):
        cache = collections.OrderedDict()
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Build a hashable key from args and kwargs
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            if key in cache:
                # Mark as most recently used
                cache.move_to_end(key, last=True)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            cache.move_to_end(key, last=True)
            if len(cache) > maxsize:
                # Evict the most recently used item
                cache.popitem(last=True)
            return result
        wrapper.cache = cache
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        # Helper to create a hashable key from args and kwargs
        def make_key(args, kwargs):
            try:
                if typed:
                    # Include types of positional and keyword arguments
                    return (
                        args,
                        tuple(sorted(kwargs.items())),
                        tuple(type(a) for a in args),
                        tuple(type(v) for v in kwargs.values()),
                    )
                else:
                    return (args, tuple(sorted(kwargs.items())))
            except TypeError:
                # Fallback for unhashable arguments: use id-based key
                return (id(args), id(kwargs))

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if maxsize is None or maxsize <= 0:
                # No caching
                return func(*args, **kwargs)

            key = make_key(args, kwargs)
            if key in cache:
                value, freq = cache[key]
                cache[key] = (value, freq + 1)
                return value

            # Compute the value and store it
            value = func(*args, **kwargs)
            cache[key] = (value, 1)

            # Evict if cache exceeds maxsize
            if len(cache) > maxsize:
                # Find key with lowest frequency
                min_freq = None
                min_key = None
                for k, (_, f) in cache.items():
                    if min_freq is None or f < min_freq:
                        min_freq = f
                        min_key = k
                if min_key is not None:
                    del cache[min_key]
            return value

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    # Use an internal dict if present, otherwise assume self is a dict-like object
    data = getattr(self, "_dict", self)
    try:
        # Try to use popitem with last=False if available (OrderedDict)
        if hasattr(data, "popitem"):
            try:
                return data.popitem(last=False)
            except TypeError:
                # popitem without last argument returns an arbitrary item
                pass
        # Fallback: manually pop the first key in insertion order
        first_key = next(iter(data))
        first_value = data[first_key]
        del data[first_key]
        return first_key, first_value
    except StopIteration:
        raise KeyError("dict is empty") from None
    except Exception as exc:
        # Re-raise any unexpected exception as a KeyError for consistency
        raise KeyError("Failed to pop item") from exc

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    # Retrieve the underlying dictionary-like storage
    storage = getattr(self, "_value", None)
    if storage is None:
        raise AttributeError("The object does not have a '_value' attribute to store data.")

    try:
        # If the key already exists, simply return its value
        if key in storage:
            return storage[key]

        # If the key is missing, set it to the provided default
        storage[key] = default

        # Mark the object as changed if a persistence flag exists
        if hasattr(self, "_p_changed"):
            self._p_changed = True

        return default

    except TypeError as exc:
        # Key is not hashable or other type error
        if hasattr(self, "logger"):
            self.logger.error(f"setdefault: invalid key type {type(key).__name__} - {exc}")
        raise ValueError(f"Invalid key type: {type(key).__name__}") from exc

    except Exception as exc:
        # Generic error handling
        if hasattr(self, "logger"):
            self.logger.error(f"setdefault: unexpected error - {exc}")
        raise

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default
    except TypeError:
        # key is not hashable or other type error; return default
        return default

def is_file_exist(file_name):
