def _reset_logging(cls):
    """Reset logging configuration to default."""
    try:
        root = logging.getLogger()
        # Remove all handlers
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        # Reset level to WARNING
        root.setLevel(logging.WARNING)
        # Reconfigure basicConfig
        logging.basicConfig(level=logging.WARNING)
    except Exception as exc:
        logging.exception("Failed to reset logging: %s", exc)

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    # If the object is a class, return its __provides__ attribute if present
    if isinstance(object, type):
        return getattr(object, "__provides__", None)

    # For instances, delegate to the class of the instance
    try:
        return directlyProvidedBy(object.__class__)
    except AttributeError:
        # If the object has no __class__ attribute, return None
        return None

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of classes")
    result = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"{cls!r} is not a class")
        if cls in seen:
            continue
        # Skip if cls is a subclass of any already kept class
        if any(issubclass(cls, other) for other in result):
            continue
        # Remove any classes that are subclasses of cls
        new_result = [other for other in result if not issubclass(other, cls)]
        new_result.append(cls)
        result = new_result
        seen.add(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean value")
    cls = type(self)
    attrs = {}
    bases = cls.__mro__ if all else (cls,)
    for base in bases:
        for name, value in base.__dict__.items():
            if name.startswith('_'):
                continue
            if callable(value) or isinstance(value, property):
                doc = None
                if isinstance(value, property):
                    doc = value.fget.__doc__ if value.fget else None
                else:
                    doc = value.__doc__
                if doc:
                    attrs[name] = doc.strip()
    return sorted(attrs.items())

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("all must be a boolean")
    cls = self.__class__
    names = []
    bases = cls.__mro__ if all else (cls,)
    for base in bases:
        if base is object:
            continue
        # Include __slots__ if defined
        if hasattr(base, "__slots__"):
            slots = base.__slots__
            if isinstance(slots, str):
                slots = (slots,)
            names.extend(slots)
        # Include class attributes that are not private and not callables
        for name, value in base.__dict__.items():
            if name.startswith("_"):
                continue
            if callable(value):
                continue
            names.append(name)
    # Remove duplicates while preserving order
    seen = set()
    unique_names = []
    for name in names:
        if name not in seen:
            seen.add(name)
            unique_names.append(name)
    return unique_names

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If the sequence is a broken interface, return it as a single-item list
    try:
        bases = getattr(sequence, "__bases__", ())
    except Exception:
        bases = ()
    if Broken in bases:
        return [sequence]

    cls = sequence.__class__
    # If the sequence is an interface or an implements spec, add it to output
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        # Try to iterate over the sequence; if it fails, treat it as a single item
        try:
            for v in sequence:
                _normalizeargs(v, output)
        except TypeError:
            output.append(sequence)

    return output

def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        import importlib
        return importlib.import_module('ase.optimize.c_optimizations')
    except ImportError:
        return False

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        return not _c_optimizations_required()
    except Exception:
        # If the required function is not available or fails, assume optimizations are ignored.
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context dictionary
    self.context = {}

    # Reinitialize bins
    try:
        # If an initial value is defined, use it to fill existing bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            if hasattr(self, "bins") and isinstance(self.bins, list):
                self.bins = [self.initial_value] * len(self.bins)
            else:
                # No existing bins; create a single bin with the initial value
                self.bins = [self.initial_value]
        else:
            # Fall back to the make_bins method if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If no method to create bins, default to an empty list
                self.bins = []
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc
    return None

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    import numpy as np

    # Validate input
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Ensure the coordinate exists in the object's variables
    if not hasattr(self, "_variables") or coord_name not in self._variables:
        raise KeyError(f"Coordinate {coord_name!r} not found in self._variables")

    # Retrieve the error array for the coordinate
    if not hasattr(self, "_errors"):
        raise AttributeError("self._errors attribute not found")
    if coord_name not in self._errors:
        raise KeyError(f"Error array for coordinate {coord_name!r} not found")

    err_arr = self._errors[coord_name]
    try:
        err_arr = np.asarray(err_arr)
    except Exception as exc:
        raise ValueError(f"Error array for coordinate {coord_name!r} could not be converted to an array: {exc}")

    # If the error array is empty or not 1‑D, return an empty array
    if err_arr.size == 0 or err_arr.ndim != 1:
        return np.array([], dtype=int)

    # Identify indices where the error is neither NaN nor zero
    mask = ~np.isnan(err_arr) & (err_arr != 0)
    return np.where(mask)[0]

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Handle None or non-iterable inputs
    if seq is None:
        return False

    # If seq is a FillRequest instance, it's valid
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # FillRequest not defined in this context
        pass

    # If seq is a Source sequence, it's invalid
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        # Source not defined; ignore
        pass

    # Helper to check if an object is a sequence (but not a string or mapping)
    def _is_sequence(obj):
        # Basic sequence types
        if isinstance(obj, (list, tuple, set, frozenset)):
            return True
        # Try to use collections.abc.Iterable if available
        try:
            from collections.abc import Iterable, Mapping
            if isinstance(obj, Iterable) and not isinstance(obj, (str, bytes)) and not isinstance(obj, Mapping):
                return True
        except Exception:
            pass
        return False

    # If seq is a sequence, check its elements
    if _is_sequence(seq):
        for item in seq:
            try:
                if isinstance(item, FillRequest):
                    return True
            except NameError:
                # If FillRequest is not defined, skip
                continue
        return False

    # Not a sequence and not a FillRequest instance
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
