    except Exception:
        return False

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the application has a spec with a manifest
    try:
        manifest = app.spec.manifest
    except AttributeError:
        raise ValueError("The application object must have a 'spec.manifest' attribute")

    if not isinstance(manifest, dict):
        raise TypeError("'spec.manifest' must be a dictionary of resources")

    # Ensure the observer_schema attribute exists and is a dictionary
    if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
        app.spec.observer_schema = {}
    observer_schema = app.spec.observer_schema

    if not isinstance(observer_schema, dict):
        raise TypeError("'spec.observer_schema' must be a dictionary")

    # Default schema to apply when none is provided
    default_schema = {
        "type": "object",
        "properties": {
            "metadata": {"type": "object"},
            "status": {"type": "object"},
        },
    }

    # Iterate over each resource in the manifest and add a default schema if missing
    for resource_name in manifest:
        if resource_name not in observer_schema:
            observer_schema[resource_name] = default_schema.copy()

    return observer_schema

