def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False
        if not os.path.exists(path):
            return False
        if not os.path.isdir(path):
            return False
        ocfl_dir = os.path.join(path, '.ocfl')
        if not os.path.isdir(ocfl_dir):
            return False
        manifest = os.path.join(ocfl_dir, 'manifest.json')
        if not os.path.isfile(manifest):
            return False
        objects_dir = os.path.join(ocfl_dir, 'objects')
        if not os.path.isdir(objects_dir):
            return False
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    status = self.status
    if status is None:
        return prefix
    # If status is an enum, use its name; otherwise convert to string
    status_str = getattr(status, 'name', str(status))
    return f"{prefix}{status_str}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Ensure the prefix is a string
    try:
        prefix = str(prefix)
    except Exception:
        prefix = ''
    # Attempt to retrieve the log from common attribute names
    log = getattr(self, 'log', None) or getattr(self, 'validation_log', None) or getattr(self, 'entries', None)
    if not log:
        return ''
    # Build the string representation
    lines = []
    if isinstance(log, (list, tuple)):
        for entry in log:
            lines.append(f"{prefix}{entry}")
    elif isinstance(log, dict):
        for key, value in log.items():
            lines.append(f"{prefix}{key}: {value}")
    else:
        lines.append(f"{prefix}{log}")
    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type check for the inventory
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary")

        # Determine the specification version if requested
        if extract_spec_version:
            type_value = inventory.get('type')
            if type_value is None:
                raise ValueError("Missing 'type' field for spec version extraction")
            # If the class defines an allowed list of spec versions, validate against it
            allowed = getattr(self, 'allowed_spec_versions', None)
            if allowed is not None and type_value not in allowed:
                raise ValueError(f"Unsupported spec version '{type_value}'")
            # Update the instance's spec_version to the extracted value
            self.spec_version = type_value

        # Validate that the inventory's spec_version (if present) matches the expected one
        if 'spec_version' in inventory:
            if inventory['spec_version'] != self.spec_version:
                raise ValueError(
                    f"Inventory spec_version '{inventory['spec_version']}' does not match expected '{self.spec_version}'"
                )

        # Ensure required top‑level fields are present
        required_fields = ['name', 'items']
        for field in required_fields:
            if field not in inventory:
                raise ValueError(f"Missing required field '{field}' in inventory")

        # Validate that 'items' is a list
        if not isinstance(inventory['items'], list):
            raise ValueError("Field 'items' must be a list")

        # Basic validation of each item (placeholder: items should be dicts)
        for idx, item in enumerate(inventory['items']):
            if not isinstance(item, dict):
                raise ValueError(f"Item at index {idx} is not a dict")

        # If all checks pass, return True
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if manifest_files is None:
        raise ValueError("manifest_files must not be None")
    # Normalize digests_used to a set
    if digests_used is None:
        digests_used_set = set()
    else:
        digests_used_set = set(digests_used)
    # Extract digests from manifest_files
    manifest_digests = set()
    for item in manifest_files:
        # Try dict-like access
        if isinstance(item, dict):
            digest = item.get('digest')
        else:
            # Try attribute access
            digest = getattr(item, 'digest', None)
        if digest:
            manifest_digests.add(digest)
    # Check for missing digests that should be used
    missing = manifest_digests - digests_used_set
    if missing:
        raise ValueError(f"Missing digests that are required but not used: {missing}")
    # Check for digests that are used but not present in the manifest
    unused = digests_used_set - manifest_digests
    if unused:
        raise ValueError(f"Digests used but not present in manifest: {unused}")
    # If everything matches, return None (or could return True)
    return None

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Validate that prior is an InventoryValidator instance
    if not isinstance(prior, InventoryValidator):
        raise TypeError(f"prior must be an InventoryValidator instance, got {type(prior).__name__}")

    # Ensure both objects have an 'inventory' attribute
    if not hasattr(self, 'inventory') or not hasattr(prior, 'inventory'):
        raise AttributeError("Both self and prior must have an 'inventory' attribute")

    # Convert inventories to plain dictionaries for safe iteration
    try:
        self_inv = dict(self.inventory)
    except Exception as exc:
        raise TypeError("self.inventory must be a mapping of item to quantity") from exc
    try:
        prior_inv = dict(prior.inventory)
    except Exception as exc:
        raise TypeError("prior.inventory must be a mapping of item to quantity") from exc

    # Check that all items in the prior inventory exist in the current inventory
    prior_keys = set(prior_inv.keys())
    self_keys = set(self_inv.keys())
    if not prior_keys.issubset(self_keys):
        missing = prior_keys - self_keys
        raise ValueError(f"Prior inventory contains items not present in current inventory: {missing}")

    # Ensure that prior quantities do not exceed current quantities
    for item, prior_qty in prior_inv.items():
        curr_qty = self_inv[item]
        try:
            if prior_qty > curr_qty:
                raise ValueError(
                    f"Prior quantity for item '{item}' ({prior_qty}) exceeds current quantity ({curr_qty})"
                )
        except TypeError as exc:
            raise TypeError(
                f"Quantities for item '{item}' must be comparable numbers"
            ) from exc

    # All checks passed
    return True

def files_list(path):
    """
    Return the files in `path`
    """
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Path does not exist: {path}")
        if os.path.isfile(path):
            return [os.path.abspath(path)]
        if os.path.isdir(path):
            files = []
            for entry in os.listdir(path):
                full = os.path.join(path, entry)
                if os.path.isfile(full):
                    files.append(os.path.abspath(full))
            return sorted(files)
        raise ValueError(f"Path is neither file nor directory: {path}")
    except OSError as e:
        raise FileNotFoundError(f"Error accessing path {path}: {e}") from e

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """

    # Ensure the internal asset storage exists
    if not hasattr(self, "_assets"):
        self._assets = {}

    def _validate_and_add(name, path):
        if not isinstance(name, str) or not name:
            raise TypeError(f"Asset name must be a non-empty string, got {name!r}")
        if not isinstance(path, str) or not path:
            raise TypeError(f"Asset path must be a non-empty string, got {path!r}")
        if not os.path.exists(path):
            raise FileNotFoundError(f"Asset file does not exist: {path}")
        if name in self._assets:
            raise ValueError(f"Asset with name '{name}' already exists")
        self._assets[name] = path
        return name, path

    # If file_path is a dict, treat it as multiple assets
    if isinstance(file_path, dict):
        added = {}
        for name, path in file_path.items():
            n, p = _validate_and_add(name, path)
            added[n] = p
        return added

    # Otherwise treat as a single asset
    name, path = _validate_and_add(basename, file_path)
    return {name: path}

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not isinstance(zip_path, str):
        return {}
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                # Skip directories
                if hasattr(info, 'is_dir'):
                    if info.is_dir():
                        continue
                else:
                    if info.filename.endswith('/'):
                        continue
                try:
                    content = zf.read(info.filename)
                except Exception:
                    continue
                base = os.path.splitext(os.path.basename(info.filename))[0]
                if base not in result:
                    result[base] = {}
                result[base][info.filename] = content
    except (FileNotFoundError, zipfile.BadZipFile, OSError):
        return {}
    return result

def files_list_from_zipfile(zip_path):
    """Return the files in `zip_path`."""
    # Support passing a ZipFile object or a path string
    if isinstance(zip_path, zipfile.ZipFile):
        zf = zip_path
        close = False
    else:
        try:
            zf = zipfile.ZipFile(zip_path, 'r')
            close = True
        except FileNotFoundError:
            raise FileNotFoundError(f"Zip file not found: {zip_path}")
        except zipfile.BadZipFile:
            raise zipfile.BadZipFile(f"Bad zip file: {zip_path}")
    try:
        # Filter out directories and .pyc files
        files = [name for name in zf.namelist()
                 if not name.endswith('/') and not name.endswith('.pyc')]
        return sorted(files)
    finally:
        if close:
            zf.close()

def fix_namespace_prefix_w(content):
    """Convert os textos cujo padrão é `w:st="` em `w-st="`."""
    if not isinstance(content, str):
        raise TypeError(f"Expected a string, got {type(content).__name__}")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if not node or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
            if matches:
                return matches[0]
        except Exception:
            # ignore malformed xpath or evaluation errors
            continue
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re

    # Get text from element or string
    if hasattr(issue, 'text') and issue.text is not None:
        text = issue.text
    else:
        text = str(issue)

    if not text:
        return None, None

    txt = text.strip().lower()

    # Find all numeric groups (including hyphenated ranges)
    nums = re.findall(r'\d+(?:-\d+)?', txt)

    # Determine number
    number = None
    if nums:
        # If more than one numeric group, first is number
        if len(nums) > 1:
            number_raw = nums[0]
            # Convert to int if single number
            if '-' not in number_raw:
                try:
                    number = int(number_raw)
                except ValueError:
                    number = number_raw
            else:
                number = number_raw
        else:
            # Only one numeric group
            # Check if the text contains a supplement keyword
            if re.search(r'\b(suppl|supp|spe|suppl\.|supp\.|spe\.)\b', txt):
                # No number, only supplement indicator
                number = None
            else:
                # Treat as number
                number_raw = nums[0]
                if '-' not in number_raw:
                    try:
                        number = int(number_raw)
                    except ValueError:
                        number = number_raw
                else:
                    number = number_raw

    # Determine supplement
    suppl = None
    # If there is a second numeric group, that's supplement
    if len(nums) > 1:
        suppl_raw = nums[1]
        if '-' not in suppl_raw:
            try:
                suppl = int(suppl_raw)
            except ValueError:
                suppl = suppl_raw
        else:
            suppl = suppl_raw
    else:
        # No second numeric group
        # Check for 'pr' after supplement keyword
        if re.search(r'\bpr\b', txt):
            suppl = 'pr'
        else:
            # Check for numeric supplement when number is None
            if number is None and nums:
                # If only one numeric group and no number, treat as supplement
                suppl_raw = nums[0]
                if '-' not in suppl_raw:
                    try:
                        suppl = int(suppl_raw)
                    except ValueError:
                        suppl = suppl_raw
                else:
                    suppl = suppl_raw

    return number, suppl

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    if hook is None:
        raise ValueError("hook must not be None")
    # Ensure the registry dictionary exists
    if not hasattr(self, "_registry"):
        self._registry = {}
    # Initialize a list for this hook if it doesn't exist
    if hook not in self._registry:
        self._registry[hook] = []

    def decorator(func):
        if not callable(func):
            raise TypeError("Registered handler must be callable")
        try:
            self._registry[hook].append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook {hook}") from exc
        return func

    return decorator

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    import math
    # Attributes that can be fractional
    attrs = ['years', 'months', 'days', 'hours', 'minutes', 'seconds', 'microseconds']
    result = {}
    # Temporary storage for propagated fractional parts
    carry = {}
    for attr in attrs:
        val = getattr(self, attr, 0)
        if isinstance(val, int):
            result[attr] = val
            continue
        # Use modf to split into whole and fractional parts
        frac, whole = math.modf(val)
        whole = int(whole)
        result[attr] = whole
        # Propagate fractional part to the next smaller unit
        if attr == 'days':
            carry['hours'] = carry.get('hours', 0) + int(round(frac * 24))
        elif attr == 'hours':
            carry['minutes'] = carry.get('minutes', 0) + int(round(frac * 60))
        elif attr == 'minutes':
            carry['seconds'] = carry.get('seconds', 0) + int(round(frac * 60))
        elif attr == 'seconds':
            carry['microseconds'] = carry.get('microseconds', 0) + int(round(frac * 1_000_000))
    # Merge carried values into result
    for k, v in carry.items():
        result[k] = result.get(k, 0) + v
    # Preserve weeks if present (they are always integers in relativedelta)
    if hasattr(self, 'weeks'):
        result['weeks'] = getattr(self, 'weeks', 0)
    return relativedelta(**result)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"

    # Attempt to read a VERSION file in the current directory
    try:
        with open("VERSION", "r", encoding="utf-8") as f:
            version = f.read().strip()
            if version:
                return version
    except Exception:
        pass

    # Attempt to read a version.py file that defines a VERSION variable
    try:
        import importlib.util
        import os

        spec = importlib.util.find_spec("version")
        if spec and spec.origin and os.path.isfile(spec.origin):
            with open(spec.origin, "r", encoding="utf-8") as f:
                for line in f:
                    if line.strip().startswith("VERSION"):
                        _, value = line.split("=", 1)
                        return value.strip().strip('"\'')
    except Exception:
        pass

    # Attempt to use pkg_resources if available
    try:
        import pkg_resources
        # Try to get the distribution name from the current package
        dist = pkg_resources.get_distribution(__name__)
        if dist and dist.version:
            return dist.version
    except Exception:
        pass

    return default

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    try:
        # Handle None or empty pieces
        if pieces is None:
            return ''
        # If pieces is a string, treat it as a single component
        if isinstance(pieces, str):
            pieces = [pieces]
        else:
            # Ensure pieces is iterable
            try:
                iter(pieces)
            except TypeError:
                raise TypeError('pieces must be an iterable of version components')
        # Convert each component to string
        pieces_str = [str(p) for p in pieces]
        # If style is a callable, delegate rendering
        if callable(style):
            return style(pieces_str)
        # Style must be a string at this point
        if not isinstance(style, str):
            raise TypeError('style must be a string or a callable')
        style = style.lower()
        if style == 'short':
            return '.'.join(pieces_str)
        elif style == 'full':
            return '.'.join(pieces_str)
        elif style == 'json':
            import json
            return json.dumps(pieces_str)
        elif style == 'tuple':
            return str(tuple(pieces_str))
        elif style == 'list':
            return str(list(pieces_str))
        else:
            raise ValueError(f'Unknown style: {style}')
    except Exception as exc:
        raise ValueError(f'Error rendering version pieces: {exc}') from exc

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Treat None as no plus
    if pieces is None:
        return '+'
    try:
        # If pieces is a string or any iterable, check for '+' presence
        if '+' in pieces:
            return '.'
        else:
            return '+'
    except TypeError:
        raise TypeError("pieces must be a string or an iterable containing '+'") from None

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import shlex

    # Prepare the list of commands to run
    if isinstance(commands, str):
        # Single command string
        cmd_list = [shlex.split(commands)]
    elif isinstance(commands, list):
        if all(isinstance(c, str) for c in commands):
            # List of command names – run each with the same args
            cmd_list = [[c] for c in commands]
        elif all(isinstance(c, list) for c in commands):
            # List of command lists
            cmd_list = commands
        else:
            raise TypeError("commands must be a string or a list of strings/lists")
    else:
        raise TypeError("commands must be a string or a list")

    # Prepare the arguments to append
    if args is None:
        args_list = []
    elif isinstance(args, str):
        args_list = shlex.split(args)
    elif isinstance(args, list):
        args_list = args
    else:
        raise TypeError("args must be a string or a list")

    # Merge environment variables
    env_dict = os.environ.copy()
    if env:
        env_dict.update(env)

    # Run each command and collect output
    outputs = []
    for cmd in cmd_list:
        full_cmd = cmd + args_list
        if verbose:
            print("Running command:", " ".join(full_cmd))
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env_dict,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=True,
            )
            outputs.append(result.stdout)
        except subprocess.CalledProcessError as e:
            err = e.stderr if e.stderr else ""
            raise RuntimeError(
                f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}. Stderr: {err}"
            ) from e

    return "".join(outputs)

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not isinstance(method, str):
        raise TypeError("method must be a string")
    global HANDLERS
    if 'HANDLERS' not in globals():
        HANDLERS = {}
    def decorate(f):
        if not callable(f):
            raise TypeError("handler must be callable")
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    for name, val in [('validate_objects', validate_objects), ('check_digests', check_digests), ('show_warnings', show_warnings)]:
        if not isinstance(val, bool):
            raise TypeError(f"{name} must be a bool, got {type(val).__name__}")

    # Determine the root path
    root = getattr(self, 'root', None) or getattr(self, 'storage_root', None)
    if root is None:
        raise AttributeError("Instance has no 'root' or 'storage_root' attribute.")
    if not isinstance(root, str):
        raise TypeError(f"root must be a string path, got {type(root).__name__}")

    import os
    import hashlib

    # Ensure the root exists
    if not os.path.exists(root):
        raise FileNotFoundError(f"Root path '{root}' does not exist.")
    if os.path.isfile(root):
        # Treat a single file as the hierarchy
        files = [root]
    elif os.path.isdir(root):
        files = []
        try:
            for dirpath, _, filenames in os.walk(root):
                for fname in filenames:
                    files.append(os.path.join(dirpath, fname))
        except Exception as e:
            if show_warnings:
                print(f"Warning: error walking the directory '{root}': {e}")
            return 0, 0
    else:
        raise ValueError(f"Root path '{root}' is neither a file nor a directory.")

    num_objects = 0
    good_objects = 0

    for file_path in files:
        num_objects += 1
        valid = True

        # Validate object existence and readability
        if validate_objects:
            try:
                with open(file_path, 'rb') as f:
                    f.read(1)  # attempt to read a byte
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: cannot read file '{file_path}': {e}")

        # Check digest if requested
        if check_digests and valid:
            try:
                hasher = hashlib.sha256()
                with open(file_path, 'rb') as f:
                    for chunk in iter(lambda: f.read(8192), b''):
                        hasher.update(chunk)
                # In a real implementation, the digest would be compared to an expected value.
                # Here we simply compute it to ensure the file can be read fully.
                _ = hasher.hexdigest()
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Warning: cannot compute digest for '{file_path}': {e}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    version = version.strip()
    if not version:
        return ""
    if not version.isdigit():
        raise ValueError("version must contain only digits")
    width = len(version)
    try:
        num = int(version)
    except ValueError:
        raise ValueError("invalid numeric value")
    num += 1
    return str(num).zfill(width)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        return self

    # Ensure required attributes exist
    if not hasattr(self, "inventory_dir"):
        raise ValueError("self.inventory_dir must be set before validation")
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise ValueError("self.root_inventory must be a dict before validation")

    # Prepare a place to record differing digests
    self.different_digests = {}

    for vdir in version_dirs:
        inv_path = os.path.join(self.inventory_dir, vdir, "inventory.json")
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inv = json.load(f)
        except FileNotFoundError:
            raise ValueError(f"Missing inventory for version '{vdir}' at {inv_path}")
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid JSON in inventory {inv_path}: {exc}")

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory {inv_path} must be a mapping of file paths to digests")

        # Ensure the inventory contains all files that exist in the root inventory
        missing_files = set(self.root_inventory) - set(inv)
        if missing_files:
            missing_list = ", ".join(sorted(missing_files))
            raise ValueError(f"Inventory {inv_path} is missing files: {missing_list}")

        # Record any digest differences
        for path, root_digest in self.root_inventory.items():
            inv_digest = inv.get(path)
            if inv_digest != root_digest:
                self.different_digests.setdefault(path, []).append(vdir)

    return self

