def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def is_mapping(node):
        return hasattr(node, 'value') and isinstance(node.value, list)

    merged = {}
    key_node_map = {}
    order = []

    for key_node, val_node in nodes:
        key = key_node.value
        if key in merged:
            existing_val = merged[key]
            if is_mapping(existing_val) and is_mapping(val_node):
                # Merge mapping node values recursively
                merged_list = deep_merge_nodes(existing_val.value + val_node.value)
                existing_val.value = merged_list
                merged[key] = existing_val
            else:
                # Last value wins
                merged[key] = val_node
        else:
            merged[key] = val_node
            key_node_map[key] = key_node
            order.append(key)

    # Build result list preserving original key node objects
    result = [(key_node_map[k], merged[k]) for k in order]
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    if parser is None:
        raise ValueError("parser cannot be None")
    if not hasattr(parser, "_actions"):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        option_strings = getattr(action, "option_strings", [])
        if option_strings:
            flags.extend(option_strings)
    # Preserve order while removing duplicates
    seen = set()
    unique_flags = []
    for flag in flags:
        if flag not in seen:
            seen.add(flag)
            unique_flags.append(flag)
    return " ".join(unique_flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Ensure we have a list of arguments to work with
    if not isinstance(unparsed_arguments, (list, tuple)):
        try:
            unparsed_arguments = list(unparsed_arguments)
        except Exception:
            raise TypeError("unparsed_arguments must be a sequence of strings")

    # If there are no subparsers, simply return the original arguments as remaining
    if not subparsers:
        return {}, list(unparsed_arguments)

    parsed_namespaces = {}
    remaining_lists = []

    for name, parser in subparsers.items():
        try:
            ns, rem = parser.parse_known_args(unparsed_arguments)
        except SystemExit:
            # If a subparser fails to parse (e.g., due to required arguments missing),
            # skip it and continue with the others.
            continue
        parsed_namespaces[name] = ns
        remaining_lists.append(rem)

    # Compute the intersection of all remaining argument lists to find arguments
    # that were not claimed by any subparser.
    if remaining_lists:
        # Start with the set of arguments from the first remaining list
        common_set = set(remaining_lists[0])
        for rem in remaining_lists[1:]:
            common_set &= set(rem)
        # Preserve the original order from the first remaining list
        remaining_args = [arg for arg in remaining_lists[0] if arg in common_set]
    else:
        remaining_args = list(unparsed_arguments)

    return parsed_namespaces, remaining_args

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    for action in getattr(parser, "_actions", []):
        for opt in getattr(action, "option_strings", []):
            if isinstance(opt, str) and opt.startswith("-"):
                flags.append(opt)
    return " ".join(flags)

def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    try:
        import click
        from borgmatic.cli.main import cli
    except Exception:
        # If we cannot import click or borgmatic's CLI, return an empty script
        return ""

    try:
        # Prefer the newer click shell completion API if available
        if hasattr(click, "shell_completion"):
            return click.shell_completion.get_completion_script("bash", cli)
        # Fallback to older click API if present
        if hasattr(click, "get_completion_script"):
            return click.get_completion_script("bash", cli)
    except Exception:
        # If any error occurs while generating the script, return an empty string
        return ""

    # If no suitable completion API is found, return an empty script
    return ""

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    import sys

    # Determine the argument list to parse
    if unparsed_arguments:
        args = list(unparsed_arguments)
    else:
        args = sys.argv[1:]

    # Create a top-level parser and add a subparsers container
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='subcommand')

    # Note: subparsers are expected to be added by the caller before invoking this function.
    # If no subparsers are added, the 'subcommand' attribute will be None.

    try:
        namespace, unknown = parser.parse_known_args(args)
    except Exception as exc:
        raise ValueError(f"Argument parsing failed: {exc}") from exc

    result = {}
    subcommand = getattr(namespace, 'subcommand', None)
    if subcommand:
        result[subcommand] = namespace
    else:
        result['global'] = namespace
    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    if unparsed_arguments is None:
        unparsed_arguments = []
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if subparsers is None:
        subparsers = {}
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser instances")

    parsed = {}
    recognized_set = set()

    for name, parser in subparsers.items():
        if not hasattr(parser, "parse_known_args"):
            raise TypeError(f"Parser for '{name}' does not have a parse_known_args method")
        ns, remaining = parser.parse_known_args(list(unparsed_arguments))
        parsed[name] = ns
        # Arguments that this parser recognized are those not in its remaining list
        recognized = [arg for arg in unparsed_arguments if arg not in remaining]
        recognized_set.update(recognized)

    # Remaining arguments are those not claimed by any subparser
    remaining_args = [arg for arg in unparsed_arguments if arg not in recognized_set]
    return parsed, remaining_args

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            continue
        for k, v in d.items():
            try:
                result[k] = result.get(k, 0) + v
            except TypeError:
                # Skip non-numeric values that cannot be summed
                continue
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''
    if not url_args:
        return url

    result = url
    for key, value in url_args.items():
        if value is None:
            continue
        # Encode the value for safe URL usage
        try:
            from urllib.parse import quote
            encoded = quote(str(value), safe='')
        except Exception:
            encoded = str(value)
        # Replace placeholders of the form {key} and :key
        result = result.replace('{' + key + '}', encoded)
        result = result.replace(':' + key, encoded)
    return result

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str):
        stripped = val.strip()
        if stripped == "":
            return True
        if stripped.lower() in ("none", "null"):
            return True
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise ValueError("parser cannot be None")
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    flags = []
    for action in actions:
        for opt in getattr(action, 'option_strings', []):
            if opt.startswith('-'):
                flags.append(opt)
    return ' '.join(flags)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None:
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result
        elif len(result) > padding:
            raise ValueError(f"number requires more than {padding} digits in base {base}")

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")

    def _process(item):
        if isinstance(item, dict):
            for k, v in list(item.items()):
                if k == register_value:
                    item[k] = register_number
                else:
                    _process(v)
        elif isinstance(item, list):
            for elem in item:
                _process(elem)

    _process(flow_params)
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError("value must be a string")
    if not isinstance(arg, str):
        raise TypeError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    seen = set()
    queue = [cls]
    while queue:
        current = queue.pop()
        for sub in current.__subclasses__():
            if sub not in seen:
                seen.add(sub)
                queue.append(sub)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate alphabet
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet contains duplicate characters")
    for ch in alphabet:
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError("alphabet elements must be single-character strings")

    # Build mapping from character to its numeric value
    mapping = {ch: i for i, ch in enumerate(alphabet)}
    base = len(alphabet)

    # Convert string to integer
    result = 0
    for char in string:
        if char not in mapping:
            raise ValueError(f"character '{char}' not in alphabet")
        result = result * base + mapping[char]

    return result

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    import os
    import tarfile
    import tempfile
    import requests

    # Ensure destination_path is a Path instance
    if not isinstance(destination_path, Path):
        destination_path = Path(destination_path)

    # Create destination directory if it does not exist
    if destination_path.exists():
        if not destination_path.is_dir():
            raise OSError(f"Destination path {destination_path} exists and is not a directory")
        # If directory exists and is not empty, raise to avoid accidental overwrite
        if any(destination_path.iterdir()):
            raise OSError(f"Destination directory {destination_path} is not empty")
    else:
        try:
            destination_path.mkdir(parents=True, exist_ok=False)
        except Exception as exc:
            raise OSError(f"Failed to create destination directory {destination_path}") from exc

    # Download the archive to a temporary file
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to download archive from {url}") from exc

    temp_file = None
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp:
            temp_file = Path(tmp.name)
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    tmp.write(chunk)
    except Exception as exc:
        if temp_file and temp_file.exists():
            temp_file.unlink()
        raise RuntimeError(f"Failed to write temporary file for archive from {url}") from exc

    # Extract the archive
    try:
        with tarfile.open(temp_file, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract archive to {destination_path}") from exc
    finally:
        # Clean up temporary file
        if temp_file and temp_file.exists():
            try:
                temp_file.unlink()
            except Exception:
                pass

    return destination_path

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # Remove leading/trailing single, double, or backtick quotes
    try:
        return re.sub(r"^[\"'`]+|[\"'`]+$", "", name)
    except Exception:
        # Fallback to simple strip if regex fails
        return name.strip('\'"')

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    # Validate input type
    if not isinstance(s, (str, bytes)):
        raise TypeError("s must be a str or bytes instance")
    if isinstance(s, bytes):
        try:
            s = s.decode('utf-8')
        except Exception as exc:
            raise ValueError("bytes input must be UTF-8 encoded") from exc

    # Resolve platform
    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1
    elif platform not in (0, 1):
        raise ValueError("platform must be 'this', 0 (Windows), or 1 (POSIX)")

    # Helper to unescape Windows quoted strings
    def _unescape_windows_quoted(text):
        result = []
        i = 0
        n = len(text)
        while i < n:
            if text[i] == '\\':
                bs_count = 0
                while i < n and text[i] == '\\':
                    bs_count += 1
                    i += 1
                if i < n and text[i] == '"':
                    # backslashes before a quote
                    result.append('\\' * (bs_count // 2))
                    if bs_count % 2 == 0:
                        # quote removed
                        i += 1
                    else:
                        # quote literal
                        result.append('"')
                        i += 1
                else:
                    # backslashes not before a quote
                    result.append('\\' * bs_count)
            else:
                result.append(text[i])
                i += 1
        return ''.join(result)

    # Regex patterns
    if platform == 1:  # POSIX
        pattern = r'''(?:"([^"]*)"|'([^']*)'|(\S+))'''
    else:  # Windows
        pattern = r'''(?:"((?:\\.|[^"\\])*)"|(\S+))'''

    tokens = []
    for match in re.finditer(pattern, s):
        quoted_double = match.group(1)
        quoted_single = match.group(2)
        unquoted = match.group(3)
        if quoted_double is not None:
            # Unescape backslashes in double-quoted POSIX strings
            token = re.sub(r'\\(.)', r'\1', quoted_double)
        elif quoted_single is not None:
            # Single-quoted strings are taken literally in POSIX
            token = quoted_single
        else:
            if platform == 1:
                # POSIX unquoted: unescape backslashes
                token = re.sub(r'\\(.)', r'\1', unquoted)
            else:
                # Windows unquoted: keep as is
                token = unquoted
        if platform == 0 and quoted_double is not None:
            # Windows: unescape quoted string according to CMD rules
            token = _unescape_windows_quoted(token)
        tokens.append(token)

    return tokens

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
        files = [line for line in result.stdout.splitlines() if line]
        files.sort()
        return ','.join(files)
    except (subprocess.CalledProcessError, FileNotFoundError):
        return ''

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip == '127.0.0.1' or ip.startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            try:
                packed = socket.inet_pton(socket.AF_INET6, ip)
                if packed == b'\x00' * 15 + b'\x01':
                    return True
            except OSError:
                if ip == '::1':
                    return True
    return False

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if matcher is None:
        raise TypeError("matcher must not be None")
    name = None
    default_provided = False
    default = None
    if isinstance(matcher, (list, tuple)):
        if len(matcher) == 0:
            raise TypeError("matcher tuple/list must contain at least a name")
        name = matcher[0]
        if len(matcher) >= 2:
            default_provided = True
            default = matcher[1]
    elif isinstance(matcher, dict):
        if 'name' not in matcher:
            raise TypeError("matcher dict must contain 'name' key")
        name = matcher['name']
        if 'default' in matcher:
            default_provided = True
            default = matcher['default']
    else:
        if not hasattr(matcher, 'name'):
            raise TypeError("matcher object must have 'name' attribute")
        name = getattr(matcher, 'name')
        if hasattr(matcher, 'default'):
            default_provided = True
            default = getattr(matcher, 'default')
    if not isinstance(name, str):
        raise TypeError("environment variable name must be a string")
    value = os.environ.get(name)
    if value is None:
        if default_provided:
            return default
        raise KeyError(f"Environment variable '{name}' not found")
    return value

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    # Validate input
    if pattern is None:
        raise TypeError("pattern cannot be None")
    # Determine the compiled regex type for compatibility
    try:
        PatternType = re.Pattern
    except AttributeError:
        PatternType = re._pattern_type
    # If already a compiled regex, return it unchanged
    if isinstance(pattern, PatternType):
        return pattern
    # If it's a string or bytes, optionally strip whitespace and compile
    if isinstance(pattern, (str, bytes)):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # Unsupported type
    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if isinstance(commands, str):
        commands_list = [commands]
    elif isinstance(commands, (list, tuple)):
        commands_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")
    if args is None:
        args_list = []
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    else:
        raise TypeError("args must be a list/tuple of strings or None")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    outputs = []
    for cmd in commands_list:
        if not isinstance(cmd, str):
            raise TypeError("each command must be a string")
        full_cmd = [cmd] + args_list
        if verbose:
            print("Running command:", " ".join(full_cmd))
        # Determine stderr handling
        stderr_option = subprocess.DEVNULL if hide_stderr else None
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                capture_output=True,
                text=True,
                stderr=stderr_option
            )
            result.check_returncode()
            outputs.append(result.stdout)
        except subprocess.CalledProcessError as e:
            msg = f"Command '{' '.join(full_cmd)}' failed with return code {e.returncode}"
            if e.stdout:
                msg += f"\nStdout: {e.stdout}"
            if e.stderr:
                msg += f"\nStderr: {e.stderr}"
            raise RuntimeError(msg) from e

    # Return a single string if only one command, otherwise a list of outputs
    return outputs[0] if len(outputs) == 1 else outputs

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        if isinstance(target, ipaddress.IPv4Address):
            return True
        ipaddress.IPv4Address(target)
        return True
    except (ValueError, TypeError):
        return False

def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate shape
    if shape is None:
        raise TypeError("shape must not be None")
    if not isinstance(shape, tuple):
        raise TypeError("shape must be a tuple of integers")
    for dim in shape:
        if not isinstance(dim, int):
            raise TypeError("shape dimensions must be integers")
        if dim < 0:
            raise ValueError("shape dimensions must be non-negative")
    # Validate dtype
    try:
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError("dtype must be a valid numpy dtype") from exc
    # Create array
    try:
        return np.empty(shape, dtype=dtype)
    except Exception as exc:
        raise ValueError(f"Could not create array with shape {shape} and dtype {dtype}") from exc

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import sys
    import logging

    config_map = {}
    error_records = []

    for fname in config_filenames:
        try:
            with open(fname, 'r') as f:
                raw = f.read()

            ext = os.path.splitext(fname)[1].lower()
            if ext == '.toml':
                import toml
                cfg = toml.loads(raw)
            elif ext in ('.yaml', '.yml'):
                import yaml
                cfg = yaml.safe_load(raw)
            elif ext == '.json':
                import json
                cfg = json.loads(raw)
            else:
                raise ValueError(f"Unsupported config file extension: {ext}")

            if not isinstance(cfg, dict):
                raise ValueError("Parsed configuration is not a dictionary")

            if overrides:
                cfg.update(overrides)

            if resolve_env:
                def expand(val):
                    if isinstance(val, str):
                        return os.path.expandvars(val)
                    elif isinstance(val, dict):
                        return {k: expand(v) for k, v in val.items()}
                    elif isinstance(val, list):
                        return [expand(v) for v in val]
                    else:
                        return val
                cfg = expand(cfg)

            config_map[fname] = cfg

        except Exception:
            record = logging.LogRecord(
                name=fname,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(sys.exc_info()[1]),
                args=(),
                exc_info=sys.exc_info()
            )
            error_records.append(record)

    return config_map, error_records

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values must not be None")
    if isinstance(values, str):
        raise TypeError("values must be an iterable of strings, not a single string")
    try:
        iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")
    bookmarks = []
    for raw in values:
        if not isinstance(raw, str):
            raise TypeError(f"Bookmark value must be a string, got {type(raw).__name__}")
        try:
            # Prefer a dedicated from_raw_value method if available
            if hasattr(Bookmark, "from_raw_value"):
                bookmark = Bookmark.from_raw_value(raw)
            else:
                bookmark = Bookmark(raw)
        except Exception as exc:
            raise ValueError(f"Failed to parse bookmark from raw value: {raw}") from exc
        bookmarks.append(bookmark)
    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Validate seq
    if seq is None:
        raise ValueError("seq cannot be None")
    # Validate bufsize
    if bufsize is not None:
        if not isinstance(bufsize, int):
            raise TypeError("bufsize must be an integer")
        if bufsize < 0:
            raise ValueError("bufsize must be non-negative")
    # Determine if seq is a sequence type
    if isinstance(seq, (list, tuple, str, bytes, bytearray)):
        # Sliceable types
        if bufsize is not None:
            try:
                seq = seq[:bufsize]
            except Exception:
                # Fallback to list conversion if slicing fails
                seq = list(seq)[:bufsize]
        return (seq, type(seq))
    elif isinstance(seq, set):
        # Sets are not sliceable; convert

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new scale requested
    if other is None:
        return self.scale

    # Validate that the new scale is numeric
    if not isinstance(other, (int, float)):
        raise TypeError("The 'other' argument must be a numeric value")

    # Validate current scale
    current_scale = getattr(self, "scale", None)
    if current_scale is None or not isinstance(current_scale, (int, float)):
        raise LenaValueError("Current scale is unknown; cannot rescale")
    if current_scale == 0:
        raise LenaValueError("Current scale is zero; cannot rescale")

    # Compute scaling factor
    factor = other / current_scale

    # Identify the last coordinate field
    fields = getattr(self, "fields", None)
    if not fields or not isinstance(fields, (list, tuple)):
        raise LenaValueError("Graph has no fields to rescale")
    last_field = fields[-1]

    # Rescale the data for the last coordinate
    data = getattr(self, "data", None)
    if data is None:
        raise LenaValueError("Graph has no data to rescale")
    if isinstance(data, dict):
        if last_field not in data:
            raise LenaValueError(f"Data for field '{last_field}' not found")
        # Multiply in place if possible
        try:
            data[last_field] = data[last_field] * factor
        except Exception as exc:
            raise LenaValueError(f"Failed to rescale data for field '{last_field}': {exc}") from exc
    else:
        # Assume array-like with shape (n_samples, n_dimensions)
        try:
            # Try to index the last column
            data[:, -1] = data[:, -1] * factor
        except Exception as exc:
            raise LenaValueError(f"Failed to rescale data array: {exc}") from exc

    # Rescale the errors for the last coordinate, if present
    errors = getattr(self, "errors", None)
    if errors is not None:
        if isinstance(errors, dict):
            if last_field in errors:
                try:
                    errors[last_field] = errors[last_field] * factor
                except Exception as exc:
                    raise LenaValueError(f"Failed to rescale errors for field '{last_field}': {exc}") from exc
        else:
            # Assume array-like with shape (n_samples, n_dimensions)
            try:
                errors[:, -1] = errors[:, -1] * factor
            except Exception:
                # If errors cannot be indexed, ignore silently
                pass

    # Update the graph's scale
    self.scale = other
    return None

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    # Retrieve edges and bin contents from histogram
    try:
        edges = getattr(hist, "edges")
    except AttributeError:
        try:
            edges = getattr(hist, "bin_edges")
        except AttributeError:
            raise AttributeError("Histogram object must have 'edges' or 'bin_edges' attribute")

    try:
        bins = getattr(hist, "bins")
    except AttributeError:
        try:
            bins = getattr(hist, "bin_contents")
        except AttributeError:
            raise AttributeError("Histogram object must have 'bins' or 'bin_contents' attribute")

    if len(edges) != len(bins) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    # Determine graph scale
    if scale is True:
        # Use histogram's scale if available
        scale_val = getattr(hist, "scale", None)
    else:
        scale_val = scale

    # Create graph instance
    try:
        graph = Graph()
    except NameError:
        raise NameError("Graph class is not defined in the current context")

    if scale_val is not None:
        try:
            graph.scale = scale_val
        except AttributeError:
            # If graph does not support setting scale directly, ignore
            pass

    # Set field names if graph supports it
    if hasattr(graph, "field_names"):
        graph.field_names = field_names

    # Prepare to add points
    for i in range(len(bins)):
        if get_coordinate == "left":
            coord = edges[i]
        elif get_coordinate == "right":
            coord = edges[i + 1]
        else:  # middle
            coord = (edges[i] + edges[i + 1]) / 2.0

        bin_val = bins[i]
        if make_value is None:
            value = bin_val
        else:
            try:
                value = make_value(bin_val)
            except Exception as exc:
                raise ValueError(f"make_value function raised an exception: {exc}") from exc

        # Build point tuple
        if isinstance(value, (tuple, list)):
            point_vals = (coord,) + tuple(value)
        else:
            point_vals = (coord, value)

        if len(point_vals) != len(field_names):
            raise ValueError(
                f"Number of values in point ({len(point_vals)}) does not match "
                f"number of field names ({len(field_names)})"
            )

        # Add point to graph
        try:
            graph.add_point(*point_vals)
        except Exception as exc:
            raise RuntimeError(f"Failed to add point to graph: {exc}") from exc

    return graph

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, it must be compatible with all bases.
    if explicit_mc is not None:
        for base in bases:
            try:
                if not issubclass(explicit_mc, type(base)):
                    raise TypeError(
                        f"Explicit metaclass {explicit_mc!r} is not a subclass of "
                        f"base metaclass {type(base)!r}"
                    )
            except TypeError:
                # If base is not a class, ignore it (Python allows non-class bases in some cases)
                continue
        return explicit_mc

    # No explicit metaclass: derive from bases.
    if not bases:
        return type

    # Gather metaclasses of all bases.
    metas = [type(b) for b in bases]
    # Find the most derived metaclass.
    most = metas[0]
    for m in metas[1:]:
        if issubclass(m, most):
            most = m
        elif not issubclass(most, m):
            # No direct subclass relationship; find a common subclass.
            # Candidates are metaclasses that are subclasses of all others.
            candidates = [
                cand for cand in metas
                if all(issubclass(cand, other) for other in metas)
            ]
            if not candidates:
                raise TypeError(
                    "metaclass conflict: no common metaclass found for bases "
                    f"{', '.join(repr(b) for b in bases)}"
                )
            # Choose the most derived candidate (longest MRO).
            most = max(candidates, key=lambda c: len(c.mro()))
    return most

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    else:
        del self[key]
        return value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # The LRU cache is expected to maintain an ordered mapping of keys to values
    # where the first item is the least recently used.  We use the OrderedDict
    # method `popitem(last=False)` to remove that item.  If the cache is empty
    # a KeyError is raised to signal that there is nothing to pop.
    if not hasattr(self, "_cache"):
        raise AttributeError("LRU cache internal structure '_cache' not found")
    if not self._cache:
        raise KeyError("LRU cache is empty")
    return self._cache.popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # The underlying storage is expected to be an OrderedDict or similar
    if not hasattr(self, "_data"):
        raise AttributeError("Missing _data attribute")
    try:
        # popitem(last=True) removes the most recently added item
        return self._data.popitem(last=True)
    except KeyError:
        raise KeyError("dict is empty")

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    # Default pattern for matching "field in (value1, value2, ...)"
    default_pattern = r'\b(?P<field>\w+)\s+in\s*\((?P<values>[^)]*)\)'
    pattern_str = getattr(self, "_in_pattern_str", default_pattern)
    if not isinstance(pattern_str, str):
        raise TypeError("in pattern must be a string")
    try:
        return re.compile(pattern_str, flags=re.IGNORECASE)
    except re.error as exc:
        raise ValueError(f"Failed to compile in-style regex: {exc}") from exc

def _create_converter(self) -> _converting._Converter:
    """Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        converter = _converting._Converter()
    except Exception as exc:
        raise RuntimeError("Failed to create parameter style converter") from exc
    return converter

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request is None:
        return False
    body = getattr(request, "body", None)
    if not body:
        return False
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # If request is None or has no path attribute, it cannot be a Matrix request
        if request is None:
            return False

        # Check the request path – Matrix endpoints typically start with "/_matrix"
        path = getattr(request, "path", None) or getattr(request, "path_info", None)
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True

        # Check the Content-Type header – Matrix uses JSON
        content_type = None
        if hasattr(request, "META") and isinstance(request.META, dict):
            content_type = request.META.get("CONTENT_TYPE")
        if isinstance(content_type, str) and content_type.lower().startswith("application/json"):
            return True

        # Some Matrix clients may include a custom header to identify the request
        headers = getattr(request, "headers", {})
        if isinstance(headers, dict):
            if headers.get("X-Matrix-Request") or headers.get("X-Matrix-Request-Id"):
                return True

        # If none of the above checks matched, assume it is not a Matrix request
        return False
    except Exception:
        # In case of any unexpected error, conservatively return False
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime instance")
    # Treat naive datetimes as UTC
    if dt.tzinfo is None:
        dt_utc = dt
    else:
        dt_utc = dt.astimezone(timezone.utc)
    # Format as ISO 8601 with trailing 'Z' to indicate UTC
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if text is None:
        return ''
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Regular expression to find URLs starting with http://, https://, or www.
    url_pattern = re.compile(r'\b(?:https?://|www\.)[^\s<>"\'()]+')
    def replace(match):
        url = match.group(0)
        # Separate trailing punctuation that should not be part of the link
        trailing = ''
        while url and url[-1] in '.,;:!?)]}':
            trailing = url[-1] + trailing
            url = url[:-1]
        href = url
        if url.startswith('www.'):
            href = 'http://' + url
        attrs = ' target="_blank" rel="noopener noreferrer"'
        return f'<a href="{href}"{attrs}>{url}</a>{trailing}'
    try:
        return url_pattern.sub(replace, text)
    except Exception:
        # In case of any unexpected error, return the original text
        return text

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    tag = tag.strip()
    if not tag:
        return False
    if len(tag) > 30:
        return False
    import re
    pattern = re.compile(r'^[A-Za-z0-9_-]+$')
    return bool(pattern.fullmatch(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise TypeError("node cannot be None")
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an ElementTree Element or similar iterable of children") from exc

    result = {}
    for child in children:
        key = child.tag
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must start with http:// or https://")

    # Handle the optional custom document path
    if document_path is not None:
        if not isinstance(document_path, str):
            raise ValueError("document_path must be a string")
        if not document_path.startswith("/"):
            document_path = "/" + document_path
    else:
        document_path = "/nodeinfo/1.0"

    # Determine the appropriate rel based on the NodeInfo version
    if "2.0" in document_path:
        rel = "http://nodeinfo.diaspora.software/ns/schema/2.0"
    else:
        rel = "http://nodeinfo.diaspora.software/ns/schema/1.0"

    # Construct the full href, ensuring no duplicate slashes
    href = url.rstrip("/") + document_path

    return {"links": [{"rel": rel, "href": href}]}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document or not isinstance(document, str):
        return None
    result = {}
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        subject = data.get("subject")
        if subject:
            result["subject"] = subject
        links = {}
        for link in data.get("links", []):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                links[rel] = href
        if links:
            result["links"] = links
        return result
    except Exception:
        pass  # fall back to XRD parsing

    # XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        subject_elem = root.find(".//Subject")
        if subject_elem is not None and subject_elem.text:
            result["subject"] = subject_elem.text.strip()
        links = {}
        for link in root.findall(".//Link"):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                links[rel] = href
        if links:
            result["links"] = links
        return result
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if not handle or '@' not in handle:
            return None
        host = handle.split('@', 1)[1]
        if not host:
            return None
        import urllib.request
        import urllib.parse
        resource = urllib.parse.quote(f'acct:{handle}')
        url = f'https://{host}/.well-known/webfinger?resource={resource}'
        with urllib.request.urlopen(url) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode('utf-8')
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if key is None:
        raise ValueError("key must not be None")
    # Build the full key chain
    key_chain = [key] + list(keys)
    current = dic
    for i, k in enumerate(key_chain):
        if k is None:
            raise ValueError("None value found in key chain")
        if i == len(key_chain) - 1:
            # last key: set the value
            current[k] = val
        else:
            # intermediate key: ensure a dict exists
            if k not in current or not isinstance(current[k], dict):
                current[k] = {}
            current = current[k]

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        if not settings_dirs:
            return []
        # Normalize settings_dirs to a list of directories
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        else:
            try:
                dirs = list(settings_dirs)
            except TypeError:
                dirs = [settings_dirs]
        result = []
        for d in dirs:
            if not os.path.isdir(d):
                continue
            try:
                for fname in os.listdir(d):
                    full_path = os.path.join(d, fname)
                    if spec_option is None:
                        result.append(full_path)
                    else:
                        # If spec_option is a string, treat it as a suffix
                        if isinstance(spec_option, str):
                            if fname.endswith(spec_option):
                                result.append(full_path)
                        # If spec_option is a callable, use it to filter
                        elif callable(spec_option):
                            try:
                                if spec_option(fname):
                                    result.append(full_path)
                            except Exception:
                                continue
                        # If spec_option is an iterable of strings, treat any match
                        else:
                            try:
                                for pattern in spec_option:
                                    if isinstance(pattern, str) and fname.endswith(pattern):
                                        result.append(full_path)
                                        break
                            except TypeError:
                                continue
            except OSError:
                continue
        return sorted(result)
    except Exception:
        return []

def ansible_config_manager(cls):
        """Gets the ansible config manager. """
        try:
            from ansible.utils.config import ConfigManager
        except Exception as exc:
            raise ImportError(f"Unable to import ConfigManager: {exc}")
        return ConfigManager()

def workspace_manager(cls):
    """Gets the workspace manager. """
    if not hasattr(cls, "_workspace_manager"):
        try:
            cls._workspace_manager = cls.WorkspaceManager()
        except AttributeError:
