def plugins_manager(cls):
        """Gets the plugin manager. """
        # Lazily create the manager if it does not exist yet.
        if not hasattr(cls, "_plugin_manager") or cls._plugin_manager is None:
            try:
                # Assume a PluginManager class is defined elsewhere in the package.
                cls._plugin_manager = PluginManager()
            except Exception as exc:
                # Wrap any exception that occurs during creation in a RuntimeError
                # to provide a clear error message to the caller.
                raise RuntimeError(
                    f"Failed to instantiate plugin manager: {exc}"
                ) from exc
        return cls._plugin_manager

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise IRValidatorException("yaml_file argument must be supplied")

    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"File not found: {yaml_file}") from e
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}") from e

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a mapping at the top level")

    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing)}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Helper to deep‑merge two dictionaries
    def _merge_dicts(dest, src):
        for k, v in src.items():
            if (
                k in dest
                and isinstance(dest[k], dict)
                and isinstance(v, dict)
            ):
                _merge_dicts(dest[k], v)
            else:
                dest[k] = v

    # Resolve includes for a single parser spec
    def _resolve(name, spec, visited):
        if name in visited:
            raise ValueError(f"Circular include detected for parser '{name}'")
        visited.add(name)

        includes = spec.pop("include", None)
        if not includes:
            return

        # Normalise to a list of include names
        if isinstance(includes, str):
            includes = [includes]
        elif isinstance(includes, (list, tuple)):
            includes = list(includes)
        else:
            raise TypeError(
                f"Include directive for parser '{name}' must be a string or list, got {type(includes)}"
            )

        for inc in includes:
            # First try to find the include in the current dict
            if inc in parser_dict:
                inc_spec = parser_dict[inc]
                _resolve(inc, inc_spec, visited)
                _merge_dicts(spec, inc_spec)
                continue

            # If not found, try to load from a file path
            try:
                import os
                if os.path.exists(inc):
                    # Try YAML first, fall back to JSON
                    try:
                        import yaml
                        with open(inc, "r", encoding="utf-8") as f:
                            inc_data = yaml.safe_load(f)
                    except Exception:
                        import json
                        with open(inc, "r", encoding="utf-8") as f:
                            inc_data = json.load(f)
                    if isinstance(inc_data, dict):
                        _merge_dicts(spec, inc_data)
                    else:
                        raise ValueError(
                            f"Included file '{inc}' does not contain a dictionary at the top level"
                        )
                    continue
            except Exception:
                pass

            # If we get here, the include could not be resolved
            raise KeyError(
                f"Included parser '{inc}' not found in parser_dict or as a file"
            )

    # Resolve all parser specs
    visited_global = set()
    for pname, pspec in list(parser_dict.items()):
        _resolve(pname, pspec, visited_global)

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Ensure we have a list of arguments to process
    args = getattr(self, "args", [])
    # Helper to fetch a value from the spec if possible
    def _spec_value(name):
        spec = getattr(self, "spec", None)
        if spec is None:
            return None
        # If spec is a mapping (has get)
        if hasattr(spec, "get"):
            try:
                return spec.get(name)
            except Exception:
                return None
        # If spec is an object with attributes
        return getattr(spec, name, None)

    for arg in args:
        # Skip non-option objects
        if not isinstance(arg, _BaseOpt):
            continue

        # Try to get value from spec first
        val = _spec_value(arg.name)
        if val is not None:
            defaults[arg.name] = val
            continue

        # Fallback to the option's own default if it exists
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # If this is a dictionary option with a nested scheme,
        # recursively gather defaults from that scheme
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            try:
                nested = arg.scheme.get_spec_defaults()
                if nested:
                    defaults[arg.name] = nested
            except Exception:
                # If nested scheme fails, ignore and continue
                pass

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Mapping of deprecated argument names to their current replacements.
    # Add or modify entries as new deprecations are introduced.
    return {
        'old_option1': 'new_option1',
        'old_option2': 'new_option2',
        # Example: 'legacy_mode': 'modern_mode',
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Validate input types
    if not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dict")
    if not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dict")

    # Retrieve deprecated argument mapping if available
    deprecated = getattr(self, "deprecated_args", None)
    if not deprecated:
        return

    # Normalize deprecated mapping to dict of old->new
    if isinstance(deprecated, set):
        deprecated = {arg: None for arg in deprecated}

    # Warn about deprecated arguments in CLI
    for old_arg, new_arg in deprecated.items():
        if old_arg in cli_args:
            msg = f"Argument '{old_arg}' is deprecated"
            if new_arg:
                msg += f"; use '{new_arg}' instead."
            else:
                msg += "."
            try:
                warnings.warn(msg, DeprecationWarning, stacklevel=2)
            except Exception:
                # Fallback to print if warnings module not available
                print(msg)

        if old_arg in answer_file_args:
            msg = f"Argument '{old_arg}' in answer file is deprecated"
            if new_arg:
                msg += f"; use '{new_arg}' instead."
            else:
                msg += "."
            try:
                warnings.warn(msg, DeprecationWarning, stacklevel=2)
            except Exception:
                print(msg)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str) or not command_name.strip():
        raise ValueError("command_name must be a non-empty string")

    # Ensure the command options mapping exists
    try:
        command_options = getattr(self, "_command_options")
    except AttributeError:
        raise RuntimeError("The object does not contain a '_command_options' attribute")

    # Retrieve the options for the requested command
    try:
        options = command_options[command_name]
    except KeyError:
        available = ", ".join(sorted(command_options.keys()))
        raise KeyError(
            f"Unknown command '{command_name}'. "
            f"Available commands: {available}"
        )

    # Ensure the result is a list
    if isinstance(options, (list, tuple)):
        return list(options)
    # If a single option or other iterable, convert to list
    try:
        return list(options)
    except TypeError:
        # Fallback: return a single-element list
        return [options]

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types and values
    if not isinstance(command_name, str) or not command_name:
        raise ValueError("command_name must be a non-empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise ValueError("argument_name must be a non-empty string")

    try:
        # Retrieve the overall specifications dictionary
        specs = getattr(self, "_specs", {})
        if not isinstance(specs, dict):
            raise TypeError("self._specs must be a dictionary")

        # Get the command-specific spec
        command_spec = specs.get(command_name)
        if command_spec is None:
            return None
        if not isinstance(command_spec, dict):
            raise TypeError(f"Specification for command '{command_name}' must be a dictionary")

        # Return the option specification, or None if it doesn't exist
        return command_spec.get(argument_name)
    except Exception as exc:
        # Wrap unexpected errors in a RuntimeError for clarity
        raise RuntimeError(f"Error retrieving option spec for command '{command_name}', "
                           f"argument '{argument_name}': {exc}") from exc

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    if args is None:
        return []
    silent = []
    try:
        for arg in args:
            if not isinstance(arg, str):
                continue
            if arg == '--':
                continue
            if arg.startswith('--'):
                name = arg[2:].split('=')[0]
                if name:
                    silent.append(name)
            elif arg.startswith('-'):
                name = arg[1:]
                if name:
                    silent.append(name)
    except Exception:
        return []
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping of argument names to values
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument names to values")
    # Retrieve the list of required argument names
    required = getattr(self, "required_args", None)
    if required is None:
        # No required arguments defined; nothing to validate
        return
    if not isinstance(required, (list, tuple, set)):
        raise TypeError("required_args must be a list, tuple, or set of names")
    # Identify any missing required arguments
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        if not options_spec:
            return required
        # Ensure args is a mapping for key lookup
        if not isinstance(args, dict):
            args_map = {}
        else:
            args_map = args
        for opt in options_spec:
            # Get option name
            if isinstance(opt, dict):
                name = opt.get('name')
                cond = opt.get('required_when')
            else:
                name = getattr(opt, 'name', None)
                cond = getattr(opt, 'required_when', None)
            if not name or cond is None:
                continue
            matched = False
            try:
                if callable(cond):
                    matched = bool(cond(args_map, command_name))
                elif isinstance(cond, (list, tuple, set)):
                    matched = command_name in cond
                elif isinstance(cond, bool):
                    matched = cond
                elif isinstance(cond, str):
                    # Treat as key in args
                    matched = bool(args_map.get(cond))
                else:
                    # Unsupported condition type; ignore
                    matched = False
            except Exception:
                matched = False
            if matched:
                required.append(name)
        return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")
    spec = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        arg_spec = spec.get(arg_name)
        if not arg_spec:
            continue
        length = arg_spec.get('length')
        if length is None:
            continue
        if not isinstance(length, int):
            raise TypeError(f"Length constraint for argument '{arg_name}' must be an integer")
        if length < 0:
            raise ValueError(f"Length constraint for argument '{arg_name}' must be non-negative")
        try:
            val_len = len(value)
        except Exception:
            # value has no length; skip validation
            continue
        if val_len > length:
            raise ValueError(f"Argument '{arg_name}' length {val_len} exceeds maximum allowed {length}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure we have a dictionary of arguments to validate
    if not isinstance(args, dict):
        return

    # Retrieve the argument definitions from the parsed YAML configuration
    arg_defs = getattr(self, "parsed_yaml", {}).get("args", {})
    if not isinstance(arg_defs, dict):
        return

    for arg_name, value in args.items():
        # Skip arguments that are not defined in the configuration
        arg_def = arg_defs.get(arg_name)
        if not isinstance(arg_def, dict):
            continue

        # Get the list of allowed choices for this argument, if any
        choices = arg_def.get("choices")
        if choices is None:
            continue

        # Normalize the choices to a set for efficient membership testing
        if isinstance(choices, (list, tuple, set)):
            allowed = set(choices)
        else:
            # If choices is a single value (e.g., a string), treat it as the only allowed value
            allowed = {choices}

        # Validate the provided value against the allowed choices
        if value not in allowed:
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value!r}. "
                f"Allowed choices are: {sorted(allowed)!r}"
            )

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    # If extra_vars is a dict, merge directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # If extra_vars is a list (or tuple), merge each dict element
    if isinstance(extra_vars, (list, tuple)):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            else:
                raise TypeError(
                    f"Each item in extra_vars must be a dict, got {type(item).__name__}"
                )
        return vars_dict

    # Unsupported type for extra_vars
    raise TypeError(
        f"extra_vars must be a dict, list, or tuple of dicts, got {type(extra_vars).__name__}"
    )

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Mapping of expected types for specific parsers
    type_map = {
        'main': {'port': int, 'debug': bool, 'timeout': int},
        'virsh': {'timeout': int, 'verbose': bool},
        'ospd': {'threads': int, 'log_level': str}
    }

    specific = type_map.get(parser_name, {})

    for key, val in list(values_dict.items()):
        if val is None:
            continue

        # Use specific type mapping if available
        if key in specific:
            target_type = specific[key]
            try:
                if target_type is bool:
                    if isinstance(val, str):
                        v = val.strip().lower()
                        if v in ('true', '1', 'yes', 'y'):
                            values_dict[key] = True
                        elif v in ('false', '0', 'no', 'n'):
                            values_dict[key] = False
                        else:
                            raise ValueError(f"Cannot convert {val!r} to bool for key {key}")
                    else:
                        values_dict[key] = bool(val)
                else:
                    values_dict[key] = target_type(val)
            except Exception as exc:
                raise ValueError(
                    f"Error converting key {key!r} with value {val!r} to {target_type.__name__}"
                ) from exc
            continue

        # Generic conversion for string values
        if isinstance(val, str):
            s = val.strip()
            # Boolean conversion
            if s.lower() in ('true', 'false', '1', '0', 'yes', 'no', 'y', 'n'):
                values_dict[key] = s.lower() in ('true', '1', 'yes', 'y')
                continue
            # Integer conversion
            if s.isdigit() or (s.startswith('-') and s[1:].isdigit()):
                try:
                    values_dict[key] = int(s)
                    continue
                except ValueError:
                    pass
            # Float conversion
            try:
                f = float(s)
                values_dict[key] = f
                continue
            except ValueError:
                pass
            # List conversion
            if ',' in s:
                values_dict[key] = [item.strip() for item in s.split(',')]
                continue

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    import pathlib

    # Validate plugin_dir
    try:
        p = pathlib.Path(plugin_dir)
    except Exception as exc:
        raise ValueError(f"Invalid plugin_dir: {plugin_dir}") from exc
    if not p.is_dir():
        raise ValueError(f"plugin_dir is not a directory: {plugin_dir}")

    # Locate the plugin spec file
    spec_file = None
    for name in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = p / name
        if candidate.is_file():
            spec_file = candidate
            break
    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec
    try:
        if spec_file.suffix.lower() == ".json":
            with spec_file.open("r", encoding="utf-8") as f:
                data = json.load(f)
        else:
            try:
                import yaml
            except ImportError as exc:
                raise RuntimeError(
                    "YAML support is required to load plugin spec"
                ) from exc
            with spec_file.open("r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
    except Exception as exc:
        raise RuntimeError(f"Failed to load plugin spec from {spec_file}") from exc

    if not isinstance(data, dict):
        raise ValueError("Plugin spec root must be a dictionary")

    # Flatten nested dictionaries
    def _flatten(d, parent_key=""):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    # Determine the configuration path to use
    config_path = getattr(self, "config_path", None)
    if config_path is None:
        # Nothing to inject if no config path is defined
        return

    # Ensure we have a string representation of the path
    try:
        config_path_str = str(config_path)
    except Exception:
        # If conversion fails, skip injection
        return

    # Environment variable name to use
    env_var = "CONFIG_PATH"

    # Inject only if the variable is not already set
    if env_var not in os.environ:
        try:
            os.environ[env_var] = config_path_str
        except Exception:
            # Silently ignore any OS-level errors (e.g., read-only env)
            pass

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path or not root:
        raise ValueError("Both 'path' and 'root' must be provided")
    norm_root = os.path.normpath(root)
    norm_path = os.path.normpath(path)

    # Ensure root ends with a separator for accurate prefix matching
    if not norm_root.endswith(os.sep):
        norm_root_sep = norm_root + os.sep
    else:
        norm_root_sep = norm_root

    # If the path is exactly the root, return an empty string
    if norm_path == norm_root:
        return ''

    # Check if the path starts with the root prefix
    if norm_path.startswith(norm_root_sep):
        return norm_path[len(norm_root_sep):]

    # If not, raise an exception
    raise ValueError(f"Path '{path}' does not start with root '{root}'")
